SOCIAL_FIELDS = ("facebook_url", "twitter_url", "youtube_url", "linkedin_url", "instagram_url", "telegram_url")


def _clear_placeholder_socials(obj):
    """Drop links to other brands' pages and bare domain placeholders like https://facebook.com/."""
    for field in SOCIAL_FIELDS:
        url = getattr(obj, field, None)
        if url is None:
            continue
        path = url.split("://", 1)[-1].split("/", 1)[1:] or [""]
        if "edugorilla" in url.lower() or not path[0].strip("/"):
            setattr(obj, field, "")


def apply_rebrand(apps, schema_editor):
    AboutUsSection = apps.get_model("adminpanel", "AboutUsSection")
    FooterSettings = apps.get_model("adminpanel", "FooterSettings")
    Notification = apps.get_model("adminpanel", "Notification")
    ExtraPage = apps.get_model("adminpanel", "ExtraPage")

    for about in AboutUsSection.objects.all():
        about.company_name = "Indore Tutorials"
        about.heading = "About Indore Tutorials"
        about.address = ADDRESS
        about.map_embed_url = MAP_EMBED_URL
        _clear_placeholder_socials(about)
        about.save()

    for footer in FooterSettings.objects.all():
        footer.copyright_text = "Copyright © 2026 Indore Tutorials. All rights reserved."
        _clear_placeholder_socials(footer)
        footer.save()

    # Notification links were saved as absolute URLs on the old domain; make them site-relative.
    for note in Notification.objects.filter(link__icontains="edutrellis.in"):
        note.link = OLD_DOMAIN_RE.sub("", note.link) or "/"
        note.save(update_fields=["link"])

    # Spell out the contact details on the seeded Contact Us page (skipped if an admin rewrote it).
    for page in ExtraPage.objects.filter(slug="contact-us", content__contains=OLD_CONTACT_TEXT):
        page.content = page.content.replace(OLD_CONTACT_TEXT, NEW_CONTACT_TEXT)
        page.save(update_fields=["content"])


